let p = msg.payload || {};
let label = String(p.y_label_pred || p.y_label || "unknown").toLowerCase();

let isNormal = label.includes("normal") || (label === "unknown" && p.y_pred === 0);
let isAlert  = label.includes("alert")  || (label === "unknown" && p.y_pred === 1);
let isAlarm  = label.includes("alarm")  || (label === "unknown" && p.y_pred === 2);

let normalMsg = { payload: isNormal };
let alertMsg  = { payload: isAlert };
let alarmMsg  = { payload: isAlarm };

return [normalMsg, alertMsg, alarmMsg];

let p = msg.payload || {};

let ts = Date.now();
if (p.timestamp !== undefined && p.timestamp !== null && p.timestamp !== "") {
    if (typeof p.timestamp === "number" && Number.isFinite(p.timestamp)) {
        ts = (p.timestamp < 1e12) ? p.timestamp * 1000 : p.timestamp;
    } else {
        let s = String(p.timestamp).trim();
        if (/^\d+(\.\d+)?$/.test(s)) {
            let num = Number(s);
            if (Number.isFinite(num)) {
                ts = (num < 1e12) ? num * 1000 : num;
            }
        } else {
            let parsed = Date.parse(s.replace(" ", "T"));
            if (isNaN(parsed)) {
                parsed = Date.parse(s);
            }
            if (!isNaN(parsed)) {
                ts = parsed;
            }
        }
    }
}

function readNum(obj, primary, fallback) {
    let raw = (obj[primary] !== undefined && obj[primary] !== null && obj[primary] !== "")
        ? obj[primary]
        : obj[fallback];
    if (raw === undefined || raw === null || raw === "") {
        return null;
    }
    let val = Number(raw);
    return Number.isFinite(val) ? val : null;
}

let tempVal = readNum(p, "temperature_celsius", "temp_c");
let humVal  = readNum(p, "humidity_percentage", "humidity_pct");
let luxVal  = readNum(p, "lux_lumen", "lux_lm");
let co2Val  = readNum(p, "CO2_ppm", "co2_ppm");

let thMsgs = [];
if (tempVal !== null) {
    thMsgs.push({ topic: "temperature", payload: tempVal, timestamp: ts });
}
if (humVal !== null) {
    thMsgs.push({ topic: "humidity", payload: humVal, timestamp: ts });
}

let luxMsg = (luxVal !== null) ? { topic: "lux", payload: luxVal, timestamp: ts } : null;
let co2Msg = (co2Val !== null) ? { topic: "co2", payload: co2Val, timestamp: ts } : null;

return [thMsgs.length ? thMsgs : null, luxMsg, co2Msg];

let p = msg.payload || {};
let ts = p.timestamp || null;

function readGauge(obj, primary, fallback, digits) {
    let raw = (obj[primary] !== undefined && obj[primary] !== null && obj[primary] !== "")
        ? obj[primary]
        : obj[fallback];
    if (raw === undefined || raw === null || raw === "") {
        return null;
    }
    let val = Number(raw);
    return Number.isFinite(val) ? { payload: Number(val.toFixed(digits)), timestamp: ts } : null;
}

let mTemp  = readGauge(p, "temperature_celsius", "temp_c", 2);
let mHumid = readGauge(p, "humidity_percentage", "humidity_pct", 2);
let mCo2   = readGauge(p, "CO2_ppm", "co2_ppm", 1);
let mLux   = readGauge(p, "lux_lumen", "lux_lm", 0);

return [mTemp, mHumid, mCo2, mLux];

let isEmptyObject =
    typeof msg.payload === "object" &&
    msg.payload !== null &&
    !Array.isArray(msg.payload) &&
    Object.keys(msg.payload).length === 0;

let isEmptyArray =
    Array.isArray(msg.payload) &&
    msg.payload.length === 0;

if (isEmptyObject || isEmptyArray) {
    let chartClear = { payload: [] };
    let normalOff  = { payload: false };
    let alertOff   = { payload: false };
    let alarmOff   = { payload: false };
    let textClear  = { payload: "" };
    let gaugeClear = { payload: 0 };

    return [chartClear, normalOff, alertOff, alarmOff, textClear, gaugeClear];
}
return null;
